use strict;
use warnings;

open my $fh, '<', '.env.test' or die "Cannot open .env.test: $!";
my %env = ();

while (<$fh>) {
    chomp;
    next if /^\s*#/ || /^\s*$/;
    if (/^([^=]+)=(.*)$/) {
        my $key = $1;
        my $val = $2;
        $key =~ s/^\s+|\s+$//g;
        $val =~ s/^\s+|\s+$//g;
        $env{$key} = $val;
    }
}
close $fh;

# Simple JSON encoding
print "{";
my @pairs = ();
foreach my $k (sort keys %env) {
    my $v = $env{$k};
    # Escape special characters for JSON
    $v =~ s/\\/\\\\/g;
    $v =~ s/"/\\"/g;
    push @pairs, "\"$k\":\"$v\"";
}
print join(",", @pairs);
print "}\n";
EOF

